//! Differential for `BigFloat::ci`. MPFR has no cosine integral, so
//! the oracle is a checked-in authoritative reference table
//! (`sympy.Ci(S(x)).n(340)`, mpmath backend; treated as a
//! mathematical fact, the γ-reference recipe) parsed by the
//! bit-exact decimal parser, plus a high-precision self-consistency
//! sweep. `Ci`'s domain is `x > 0`; the table and the sweep stay
//! positive.

#![cfg(all(unix, feature = "differential-mpfr"))]

mod differential;

use differential::{next_i64_in, sweep_size, TRANSCENDENTAL_PRECISIONS};
use pfloat::{BigFloat, RoundingMode};

fn close_within(a: &BigFloat, b: &BigFloat, bits: u32) -> bool {
    let (diff, _) = a.sub(b, RoundingMode::NearestEven);
    let abs = diff.abs();
    if abs.is_zero() {
        return true;
    }
    let p = a.precision().max(b.precision());
    let two = BigFloat::try_from_i64_exact(2, p).unwrap();
    let mut bound = b.abs();
    if bound.is_zero() {
        bound = BigFloat::try_from_i64_exact(1, p).unwrap();
    }
    for _ in 0..bits {
        bound = bound.div(&two, RoundingMode::NearestEven).0;
    }
    matches!(
        abs.partial_cmp(&bound).0,
        Some(core::cmp::Ordering::Less | core::cmp::Ordering::Equal)
    )
}

/// `(numerator, denominator, Ci(numerator/denominator))`. Source:
/// `sympy.Ci(S(x)).n(340)` (mpmath backend).
const CI_TABLE: &[(i64, i64, &str)] = &[
    (1, 2, "-0."),
    (1, 1, "0."),
    (2, 1, "0."),
    (3, 1, "0."),
    (5, 1, "-0."),
    (8, 1, "0."),
    (13, 1, "0."),
    (50, 1, "-0."),
    (100, 1, "-0."),
    (500, 1, "-0."),
    (2000, 1, "0."),
    (5000, 1, "-0."),
];

#[test]
fn ci_matches_authoritative_table() {
    for &p in TRANSCENDENTAL_PRECISIONS {
        for &(num, den, refstr) in CI_TABLE {
            let x = {
                let n = BigFloat::try_from_i64_exact(num, p).unwrap();
                if den == 1 {
                    n
                } else {
                    n.div(
                        &BigFloat::try_from_i64_exact(den, p).unwrap(),
                        RoundingMode::NearestEven,
                    )
                    .0
                }
            };
            let (got, _) = x.ci(RoundingMode::NearestEven);
            let want = BigFloat::parse_str(refstr, p, RoundingMode::NearestEven)
                .unwrap()
                .0;
            assert!(
                close_within(&got, &want, p - 2),
                "Ci({num}/{den}) at p={p}: got {got}, want {want}"
            );
        }
    }
}

#[test]
fn ci_self_consistent() {
    let mut state: u64 = u64::from_le_bytes(*b"pfl6mci_");
    let cases = sweep_size().min(200);
    for &p in TRANSCENDENTAL_PRECISIONS {
        for _ in 0..cases {
            let a = next_i64_in(&mut state, 1, 3000);
            let (lo, _) = BigFloat::try_from_i64_exact(a, p)
                .unwrap()
                .ci(RoundingMode::NearestEven);
            let hi = {
                let (r, _) = BigFloat::try_from_i64_exact(a, p + 96)
                    .unwrap()
                    .ci(RoundingMode::NearestEven);
                r.round_to_precision(p, RoundingMode::NearestEven)
                    .expect("p >= 1")
                    .0
            };
            assert!(
                close_within(&lo, &hi, p - 8),
                "Ci({a}) self-consistency at p={p}: lo={lo}, hi={hi}"
            );
        }
    }
}
